INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('三方共同投資，讓臺灣營德兼具國際製造視野、在地供應韌性與長期經營基礎。', '關於營德');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('從台塑到營德，厚植製造實力', '關於營德');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('臺灣營德的製造故事，源自台塑塑膠加工組。1983 年，加工組於高雄前鎮廠起步，開始生產購物袋；1984 年，市場袋、清潔袋正式加入產品線，逐步累積袋品製造的基礎與經驗。', '關於營德');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('1989 年，新港廠整地擴建；1991 年正式投產，並啟用全自動拌料輸送系統。隨著市場需求與設備能力提升，產品線也持續延伸。', '關於營德');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('2004 年，前鎮廠遷廠合併，新港成為主要生產基地；2008 年，全球產品配置重整，讓製造資源更聚焦於具技術與品質優勢的產品。', '關於營德');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('2014 年，台塑塑膠加工組改組，成立「臺灣營德股份有限公司」。臺灣營德延續既有的製造經驗，結合 INTEPLAST GROUP 的全球技術與營運管理，並持續作為台塑相關企業的一員，開啟新的篇章。', '關於營德');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('2015 年，越南營德公司成立，進一步拓展海外製造布局。透過臺灣與越南生產基地的相互支援，結合 INTEPLAST GROUP 的全球資源與技術經驗，逐步強化產能配置與國際市場供應能力。', '關於營德');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('從前鎮的第一只購物袋，到新港的持續精進；我們把累積多年的製造經驗，轉化為面向未來的可靠承諾。', '關於營德');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('臺灣營德的製造歷程', '關於營德');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('故事始於高雄前鎮廠，從袋品生產出發，逐步發展為今日的製造基地。', '關於營德');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('集團肯定，來自實際的生產表現', '關於營德');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('臺灣營德連續五年獲頒 INTEPLAST GROUP Excellence Award 卓越獎。', '關於營德');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('INTEPLAST GROUP 卓越獎與年度最大進步營運單位獎座', '關於營德');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('抽取式設計，取得美國專利', '關於營德');
