INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('綠色標章產品', '永續發展');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('讓每一次選擇，<br>更靠近綠色生活。', '永續發展');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('臺灣營德以通過環保標章的產品，回應日常生活對環境友善選擇的需求。從產品設計到使用，我們以可被辨識的綠色承諾，陪伴每一個乾淨安心的日常。', '永續發展');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('認識環保標章產品', '永續發展');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('環保標章介紹', '永續發展');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('環保標章是什麼', '永續發展');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('以綠葉環抱地球，<br>辨識更友善的選擇。', '永續發展');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('環保標章以綠色葉片環繞地球的意象，傳遞守護環境、珍惜資源的理念。取得標章的產品，須符合環境部公告的規格標準並獲得使用證書，讓消費者採購時有清楚的辨識依據。', '永續發展');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('綠色消費的觀念在歐美環保運動中逐漸發展，德國、加拿大、日本與北歐等地也陸續建立環保標章制度。台灣於民國81年推動環保標章，鼓勵製造端減少污染與資源消耗，也讓使用者能支持可回收、低污染與省資源的產品。', '永續發展');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('環保標章規格標準', '永續發展');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('環保標章產品查詢', '永續發展');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('依 ISO 14024 原則建立', '永續發展');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('環保標章採用國際第一類環境標誌的原則與程序，以市場機制鼓勵環境衝擊較低的產品與服務。', '永續發展');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('從產品生命週期看環境', '永續發展');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('原料取得、生產、銷售、使用到廢棄，各階段的減量、回收、低污染與資源效率都是重要考量。', '永續發展');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('持續擴大的綠色選擇', '永續發展');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('自民國82年公布首批標準以來，環保標章已涵蓋14大產品類別、超過百項產品項目。', '永續發展');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('我們的綠色標章產品', '永續發展');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('兩款取得環保標章的日常用品', '永續發展');
INSERT OR IGNORE INTO ui_strings (zh, page) VALUES ('產品規格與標章資訊以環境部「淨零綠生活資訊平台」公開資料為準；點選卡片可查看各產品的完整資料。', '永續發展');
