INSERT OR IGNORE INTO translations (entity, entity_id, field, lang, value) SELECT 'ui', id, 'text', 'en', 'INTEPLAST TAIWAN CORPORATION | Can Liner, Draw Tape & Zipper Bag Manufacturer' FROM ui_strings WHERE zh = '臺灣營德股份有限公司 | INTEPLAST TAIWAN CORPORATION';
INSERT OR IGNORE INTO translations (entity, entity_id, field, lang, value) SELECT 'ui', id, 'text', 'en', 'INTEPLAST TAIWAN CORPORATION is a joint venture of Formosa Plastics and INTEPLAST USA, manufacturing can liners, draw tape liners, produce bags, zipper bags, gloves, masking film and Scale Sheet for household and industrial use.' FROM ui_strings WHERE zh = '臺灣營德股份有限公司 (INTEPLAST TAIWAN CORPORATION) 為台塑關係企業與 INTEPLAST USA 合資大廠，專業生產清潔袋、拉繩袋、蔬果袋、夾鏈袋、手套/遮蔽膠帶與 Scale Sheet，提供多元日常與工業應用情境。';
INSERT OR IGNORE INTO translations (entity, entity_id, field, lang, value) SELECT 'ui', id, 'text', 'en', 'Formosa Plastics Group · Can Liner Specialist' FROM ui_strings WHERE zh = '台塑企業清潔袋專業製造';
INSERT OR IGNORE INTO translations (entity, entity_id, field, lang, value) SELECT 'ui', id, 'text', 'en', 'A joint venture of Formosa Plastics, INTEPLAST USA and Chang Gung Biotech. Built on Formosa resin, our Chiayi Xingang and Vietnam plants run automated extrusion for can liners and draw-tape bags, alongside produce and zipper bags, plus the group''s patented pop-up Scale Sheet.' FROM ui_strings WHERE zh = '台塑企業、INTEPLAST USA 與長庚生技合資建立公司。以台塑原料自製清潔袋與拉繩袋，嘉義新港、越南基地自動化吹膜；另有蔬果袋、夾鏈袋，以及集團專利抽取式 Scale Sheet。';
