INSERT OR IGNORE INTO translations (entity, entity_id, field, lang, value) SELECT 'ui', id, 'text', 'en', 'In Xingang, we turn reliable quality, precise processes, and environmental thinking into work global markets can count on—responding to every need that keeps moving forward.' FROM ui_strings WHERE zh = '在新港，我們把穩定品質、精密製程與環境思維，做成全球市場可以信賴的日常。臺灣營德持續用更好的製造，回應每一個正在前進的需求。';
