INSERT OR IGNORE INTO translations (entity, entity_id, field, lang, value) SELECT 'ui', id, 'text', 'en', 'Contact the export sales team at INTEPLAST TAIWAN CORPORATION. Rm. 609, 6F., No. 205, Dunhua N. Rd., Songshan Dist., Taipei City, Taiwan. Tel: +886-2-2712-2211 #8109.' FROM ui_strings WHERE zh = '聯繫臺灣營德股份有限公司 (INTEPLAST TAIWAN) 外銷業務團隊。地址：臺北市松山區敦化北路205號6樓609室，電話：02-2712-2211 #8109。';
