INSERT OR IGNORE INTO translations (entity, entity_id, field, lang, value) SELECT 'ui', id, 'text', 'en', 'Green Mark Certified Products | INTEPLAST TAIWAN CORPORATION' FROM ui_strings WHERE zh = '環保標章產品｜臺灣營德股份有限公司';
INSERT OR IGNORE INTO translations (entity, entity_id, field, lang, value) SELECT 'ui', id, 'text', 'en', 'Green Mark certified products from INTEPLAST TAIWAN: Formosa eco draw tape liners and Formosa eco can liners.' FROM ui_strings WHERE zh = '臺灣營德環保標章產品：台塑環保拉繩清潔袋與台塑環保清潔袋。';
INSERT OR IGNORE INTO translations (entity, entity_id, field, lang, value) SELECT 'ui', id, 'text', 'en', 'GREEN LABEL PRODUCTS' FROM ui_strings WHERE zh = '綠色標章產品';
INSERT OR IGNORE INTO translations (entity, entity_id, field, lang, value) SELECT 'ui', id, 'text', 'en', 'INTEPLAST TAIWAN responds to everyday eco-friendly needs with Green Mark certified products. From design to use, our recognizable green commitment accompanies clean, peaceful daily living.' FROM ui_strings WHERE zh = '臺灣營德以通過環保標章的產品，回應日常生活對環境友善選擇的需求。從產品設計到使用，我們以可被辨識的綠色承諾，陪伴每一個乾淨安心的日常。';
INSERT OR IGNORE INTO translations (entity, entity_id, field, lang, value) SELECT 'ui', id, 'text', 'en', 'Explore Green Mark Products' FROM ui_strings WHERE zh = '認識環保標章產品';
INSERT OR IGNORE INTO translations (entity, entity_id, field, lang, value) SELECT 'ui', id, 'text', 'en', 'About Green Mark' FROM ui_strings WHERE zh = '環保標章介紹';
INSERT OR IGNORE INTO translations (entity, entity_id, field, lang, value) SELECT 'ui', id, 'text', 'en', 'WHAT IS THE GREEN MARK' FROM ui_strings WHERE zh = '環保標章是什麼';
INSERT OR IGNORE INTO translations (entity, entity_id, field, lang, value) SELECT 'ui', id, 'text', 'en', 'The Green Mark uses green leaves surrounding the Earth to convey environmental protection and resource conservation. Certified products meet official standards from the Ministry of Environment, providing clear purchasing guidance.' FROM ui_strings WHERE zh = '環保標章以綠色葉片環繞地球的意象，傳遞守護環境、珍惜資源的理念。取得標章的產品，須符合環境部公告的規格標準並獲得使用證書，讓消費者採購時有清楚的辨識依據。';
INSERT OR IGNORE INTO translations (entity, entity_id, field, lang, value) SELECT 'ui', id, 'text', 'en', 'Green consumerism evolved from global environmental movements. Taiwan introduced its Green Mark system in 1992, encouraging manufacturers to reduce pollution and resource consumption.' FROM ui_strings WHERE zh = '綠色消費的觀念在歐美環保運動中逐漸發展，德國、加拿大、日本與北歐等地也陸續建立環保標章制度。台灣於民國81年推動環保標章，鼓勵製造端減少污染與資源消耗，也讓使用者能支持可回收、低污染與省資源的產品。';
INSERT OR IGNORE INTO translations (entity, entity_id, field, lang, value) SELECT 'ui', id, 'text', 'en', 'Green Mark Standards' FROM ui_strings WHERE zh = '環保標章規格標準';
INSERT OR IGNORE INTO translations (entity, entity_id, field, lang, value) SELECT 'ui', id, 'text', 'en', 'Search Certified Products' FROM ui_strings WHERE zh = '環保標章產品查詢';
INSERT OR IGNORE INTO translations (entity, entity_id, field, lang, value) SELECT 'ui', id, 'text', 'en', 'Built on ISO 14024 Principles' FROM ui_strings WHERE zh = '依 ISO 14024 原則建立';
INSERT OR IGNORE INTO translations (entity, entity_id, field, lang, value) SELECT 'ui', id, 'text', 'en', 'Adheres to Type I environmental labeling principles under ISO 14024 to encourage eco-friendly products.' FROM ui_strings WHERE zh = '環保標章採用國際第一類環境標誌的原則與程序，以市場機制鼓勵環境衝擊較低的產品與服務。';
INSERT OR IGNORE INTO translations (entity, entity_id, field, lang, value) SELECT 'ui', id, 'text', 'en', 'Life Cycle Assessment' FROM ui_strings WHERE zh = '從產品生命週期看環境';
INSERT OR IGNORE INTO translations (entity, entity_id, field, lang, value) SELECT 'ui', id, 'text', 'en', 'Considers environmental impact across raw materials, manufacturing, sales, usage, and disposal.' FROM ui_strings WHERE zh = '原料取得、生產、銷售、使用到廢棄，各階段的減量、回收、低污染與資源效率都是重要考量。';
INSERT OR IGNORE INTO translations (entity, entity_id, field, lang, value) SELECT 'ui', id, 'text', 'en', 'Expanding Eco Options' FROM ui_strings WHERE zh = '持續擴大的綠色選擇';
